'use strict';
let D,year=1956,page='overview',scope='year',query='',saved=[];
try{saved=JSON.parse(localStorage.getItem('football-archive-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={overview:['◫','시즌 둘러보기'],teams:['⚑','클럽 아카이브'],players:['♙','선수 아카이브'],competitions:['♜','대회 아카이브'],transfers:['⇄','이적시장'],favorites:['☆','나의 컬렉션']};
const titles={overview:['축구의 시간을 걷다','그 시절의 팀, 그 시절의 선수. 위대한 경기의 모든 시작을 만나보세요.'],teams:['그 시대를 빛낸 클럽들','클래식 결승 선발 11명과 당시 전술을 살펴보세요.'],players:['이름만으로 기억되는 선수들','아카이브에 수록된 실제 결승 선발 선수와 발롱도르 수상자.'],competitions:['트로피를 향한 여정','새롭게 탄생하고, 이름을 바꾸고, 역사 속으로 사라진 대회들.'],transfers:['새로운 역사의 첫 계약','시대를 바꾼 주요 이적을 연도별로 되짚어보세요.'],favorites:['나만의 축구 박물관','다시 만나고 싶은 팀과 시즌을 이곳에 모아두세요.'],awards:['위대한 이름, 발롱도르','1956년부터 이어진 남자 발롱도르의 모든 수상 기록.'],sources:['기록에 정직한 아카이브','수록 범위와 기준, 원본 자료를 확인하세요.']};
const awardSource='https://www.uefa.com/ballondor/news/0287-195e642735da-0594342b9554-1000--history-of-the-ballon-d-or-all-the-winners/';
const season=()=>`${year-1}/${String(year).slice(-2)}`;
function comps(){return D.competitions.filter(c=>year>=c.start&&year<=c.end&&(!c.cycle||(c.name.includes('월드컵')?year%4===2:(year===2021||year!==2020&&year%4===0))))}
function currentTeams(){return D.teams.filter(t=>t.year===year)}
function badge(t){return `<div>${crestHTML(t.en,{size:'large'})}<div class="badge-label">현재 엠블럼 · 과거 디자인 미검증</div></div>`}

function saveBtn(key){return `<button class="save ${saved.includes(key)?'saved':''}" data-save="${key}" aria-label="${saved.includes(key)?'컬렉션에서 제거':'컬렉션에 저장'}" aria-pressed="${saved.includes(key)}">${saved.includes(key)?'★':'☆'}</button>`}
function club(t){let i=D.teams.indexOf(t);return `<article class="club-card" data-team="${i}" tabindex="0" role="button" aria-label="${t.year} ${t.name} 선발 명단 보기"><div class="club-top">${badge(t)}${saveBtn('team:'+i)}</div><h3>${t.name}</h3><div class="english">${t.en}</div><div class="club-meta"><span>${t.country}</span><span>·</span><span>${t.year-1}/${String(t.year).slice(-2)} 결승</span><span class="chip">${t.formation}</span></div><div class="club-bottom"><span>선발 11명 수록</span><span>팀 살펴보기 ↗</span></div></article>`}
function section(title,sub,link,label){return `<div class="section-heading"><h2>${title}${sub?`<small>${sub}</small>`:''}</h2>${link?`<button class="text-button" data-page="${link}">${label||'전체 보기'} ↗</button>`:''}</div>`}
function empty(text){return `<div class="empty">${text}<button class="year-bookmark" data-all>수록된 모든 연도 보기 →</button></div>`}
function overview(){const teams=currentTeams();let stories={1956:['모든 전설에는<br>첫 페이지가 있다.','파리에서 열린 첫 유러피언컵 결승.<br>레알 마드리드와 스타드 드 랭스가 만들어낸 4–3의 드라마.'],1968:['맨체스터의 꿈이<br>유럽의 정상에 서다.','버스비의 아이들, 그리고 조지 베스트.<br>맨체스터 유나이티드의 첫 번째 유럽 정상.'],1972:['공간을 지배하고,<br>축구를 바꾸다.','요한 크라위프와 아약스의 토털 풋볼.<br>포지션을 넘어선 움직임이 새로운 시대를 열었습니다.'],1989:['밀라노에서 시작된<br>아름다운 혁명.','사키의 압박, 네덜란드 삼총사의 재능.<br>유럽을 흔든 AC 밀란의 4–0 결승전.'],1999:['끝날 때까지<br>끝난 것이 아니다.','캄 노우의 기적과 역사적인 트레블.<br>추가시간 두 골이 바꿔놓은 맨체스터의 역사.'],2009:['하나의 공,<br>완벽에 가까운 축구.','과르디올라와 메시, 차비, 이니에스타.<br>바르셀로나가 첫 트레블을 완성한 로마의 밤.'],2014:['오래 기다린 꿈,<br>라 데시마.','라모스의 헤더로 다시 쓰인 결승전.<br>레알 마드리드, 마침내 열 번째 유럽 정상.']};const story=stories[year]||['시간을 건너,<br>그라운드로 돌아가다.',`${year}년의 발롱도르와 유럽 챔피언.<br>그해의 기록을 따라 축구 역사를 탐색하세요.`];return `<section class="hero"><div><div class="eyebrow">THE SEASON THAT MADE HISTORY · ${season()}</div><h2>${story[0]}</h2><p>${story[1]}</p><button class="hero-btn" ${teams.length?'data-team="'+D.teams.indexOf(teams[0])+'"':'data-page="competitions"'}>${teams.length?'이 시대의 팀 만나기':'이 시대의 대회 만나기'}<span>↗</span></button></div><div class="hero-year">${year}<small>THE BEAUTIFUL GAME</small></div></section>
<div class="stats"><div class="stat"><div class="stat-icon">⚑</div><div><small>이 연도의 클래식 팀</small><strong>${teams.length}</strong><em>팀 수록</em></div></div><div class="stat"><div class="stat-icon">♜</div><div><small>유럽 챔피언 · ${season()}</small><strong>${D.champions[year]}</strong></div></div><div class="stat"><div class="stat-icon">⇄</div><div><small>이 연도의 주요 이적</small><strong>${D.transfers.filter(t=>t.year===year).length}</strong><em>건 수록</em></div></div></div>
<div class="two-col"><div>${section('그 시절, 그 팀',season(),'teams','클럽 아카이브')}<div class="club-grid">${teams.map(club).join('')}</div>${!teams.length?empty('이 연도의 선발 명단은 아직 수록되지 않았습니다.<br>발롱도르와 유럽 챔피언 기록은 확인할 수 있습니다.'):''}<p class="note">ⓘ 시즌 종료 연도 기준 · 수록 명단은 해당 유럽 결승의 선발 11명입니다.<br>엠블럼은 현재 식별용 이미지이며, 과거 연도의 디자인과 다를 수 있습니다.</p></div><div>${section('그해의 발롱도르','','awards','역대 수상자')}<article class="award-card"><div class="eyebrow">BALLON D’OR · ${year}</div><div class="trophy"><div class="gold-ball" aria-hidden="true">⬡</div></div><h3>${D.awards[year]}</h3><p>${year===2020?'코로나19로 시상 취소':'남자 발롱도르 수상자'}</p><button data-award="${year}">수상 기록 살펴보기 &nbsp; ↗</button></article></div></div>
${section('시간을 여행하는 또 다른 방법','','transfers','이적시장 보기')}<div class="filters">${[1956,1968,1972,1989,1999,2009,2014,2026].map(y=>`<button data-year="${y}" class="${year===y?'active':''}">${y} ${({1956:'첫 유럽 챔피언',1968:'버스비의 꿈',1972:'토털 풋볼',1989:'사키의 밀란',1999:'트레블',2009:'로마의 밤',2014:'라 데시마',2026:'현재'})[y]}</button>`).join('')}</div><div class="notice">이 아카이브는 주요 역사 기록을 담은 첫 번째 에디션입니다. 전 세계 모든 팀·선수·대회를 포괄하지 않으며, 경기 영상과 실시간 이적 정보는 직접 제공하지 않습니다. <button class="text-button" data-page="sources">수록 범위 확인 ↗</button></div>`}
function toolbar(placeholder){return `<div class="toolbar"><div class="filters"><button data-scope="year" class="${scope==='year'?'active':''}">${year}년</button><button data-scope="all" class="${scope==='all'?'active':''}">전체 연도</button></div><input id="filter" class="inline-search" type="search" placeholder="${placeholder}" value="${esc(query)}" aria-label="${placeholder}"></div>`}
function filterText(s){return s.toLowerCase().includes(query.toLowerCase())}
function teamsPage(){let a=D.teams.filter(t=>(scope==='all'||t.year===year)&&filterText(t.name+' '+t.en+' '+t.country));return toolbar('클럽명 또는 국가 검색')+`<div class="section-heading"><span class="result-count">${a.length}개 팀 · 시즌별 결승 선발 명단</span></div><div class="club-grid all-clubs">${a.map(club).join('')}</div>`+(!a.length?empty('조건에 맞는 팀 명단이 없습니다.<br>1956 · 1968 · 1972 · 1989 · 1999 · 2009 · 2014년의 클래식 팀을 탐색해 보세요.'):'')+`<p class="note">현재 엠블럼을 표시합니다. 해당 연도의 역사적 엠블럼 디자인은 검증되지 않았습니다.</p>`}
function playersPage(){let a=[];D.teams.filter(t=>scope==='all'||t.year===year).forEach(t=>t.players.forEach(p=>{if(filterText(p.name+' '+t.name))a.push({p,t})}));return toolbar('선수명 또는 클럽 검색')+section('그라운드의 주인공',`${a.length}개의 선수·시즌 기록`,'awards','발롱도르 역대 수상자')+`<div class="player-grid">${a.map(({p,t})=>`<button class="player" data-player="${D.teams.indexOf(t)}:${t.players.indexOf(p)}"><span class="initial">${p.pos}</span><div><h3>${p.name}</h3><p>${t.name} · ${t.year}</p></div></button>`).join('')}</div>`+(!a.length?empty('해당 조건의 선수가 수록되지 않았습니다. 전체 연도에서 검색해 보세요.'):'')+`<p class="note">명단은 결승 선발 기준입니다. 선수의 전체 커리어 및 시즌 전체 등록 선수 명단은 미수록입니다.</p>`}
function competitionPage(){let a=comps();return section('그해의 주요 대회',`${a.length}개 수록`)+`<div class="competition-grid">${a.map(c=>`<article class="competition"><div class="comp-icon">♜</div><span class="chip">${c.kind}</span><h3>${c.name==='UEFA 컨퍼런스리그'&&year<2025?'UEFA 유로파 컨퍼런스리그':c.name}</h3><small>${c.en}</small><p>${c.note}</p><a class="source-link" href="https://en.wikipedia.org/wiki/${encodeURIComponent(c.en.replace(/’/g,"'"))}" target="_blank" rel="noopener">대회 역사 읽기 ↗</a></article>`).join('')}</div><div class="panel"><h2>${season()} 유럽 챔피언</h2><p><strong>${D.champions[year]}</strong> · ${year<=1992?'유러피언컵':'UEFA 챔피언스리그'}</p><a href="https://www.uefa.com/uefachampionsleague/history/seasons/${year}/" target="_blank" rel="noopener">UEFA 공식 시즌 기록 · 경기 및 영상 ↗</a></div><p class="note">클럽 대회는 종료 연도 기준, 국가대표 대회는 개최 연도 기준입니다. 대회 목록은 주요 대회 일부이며, 하위 리그·지역 대회는 미수록입니다. 1956년의 페어스컵은 1955–58년 첫 대회 기간에 포함됩니다.</p>`}
function transferPage(){let a=D.transfers.filter(t=>(scope==='all'||t.year===year)&&filterText(t.name+' '+t.origin+' '+t.dest));return toolbar('선수 또는 이적 구단 검색')+section('역사를 바꾼 이적',`${a.length}건 수록`)+`<div class="table-wrap"><table><thead><tr><th>연도</th><th>선수</th><th>이전 소속 → 새 소속</th><th>이적료</th><th>자료</th></tr></thead><tbody>${a.map(t=>`<tr><td>${t.year}</td><td><b>${t.name}</b></td><td>${t.origin}<span class="transfer-arrow">→</span>${t.dest}</td><td class="fee">${t.fee}</td><td><a class="source-link" href="${t.source}" target="_blank" rel="noopener" aria-label="${t.name} ${t.year}년 이적 자료 확인">↗</a></td></tr>`).join('')}</tbody></table></div>`+(!a.length?empty('이 연도에 수록된 이적 기록이 없습니다.<br>전체 이적이 없었다는 의미는 아닙니다.'):'')+`<p class="note">주요 이적 ${D.transfers.length}건을 선별한 역사 목록입니다. 실시간 거래·소문은 제공하지 않습니다.<br>이적료는 명목 유로 기준의 널리 알려진 기본 금액만 기재했습니다. 보너스·환율·인플레이션을 반영하지 않으며, 미표기는 0원이나 비공개를 뜻하지 않습니다.</p>`}
function awardsPage(){return `<div class="wide-hero"><h2>Ballon d’Or</h2><p>1956 — 2026 · 수상자 70개 연도 · 2020년 시상 취소</p><a class="source-link" href="${awardSource}" target="_blank" rel="noopener">UEFA 역대 수상자 원문 ↗</a></div><div class="award-grid">${Object.entries(D.awards).map(([y,n])=>`<button class="award-item ${+y===year?'active':''}" data-award="${y}"><strong>${y}</strong><h3>${n}</h3></button>`).join('')}</div>`}
function favoritesPage(){const ts=saved.filter(k=>k.startsWith('team:')).map(k=>D.teams[+k.split(':')[1]]).filter(Boolean),ys=saved.filter(k=>k.startsWith('year:')).map(k=>+k.split(':')[1]);return `<div class="toolbar"><p class="result-count">이 브라우저에 저장됩니다.</p><button class="year-bookmark" data-save="year:${year}">${saved.includes('year:'+year)?'★ 저장된 시즌 해제':'☆ '+year+'년 시즌 저장'}</button></div>`+section('저장한 시즌',`${ys.length}개`)+`<div class="filters">${ys.map(y=>`<button data-jump="${y}">${y} · ${D.awards[y]} ↗</button>`).join('')}</div><div class="compact-heading">${section('저장한 팀',`${ts.length}개`)}</div><div class="club-grid all-clubs">${ts.map(club).join('')}</div>`+(!ys.length&&!ts.length?`<div class="empty">아직 저장한 기록이 없습니다.<br>클럽 카드의 ☆을 눌러 나만의 컬렉션을 시작해 보세요.</div>`:'')}
function sourcesPage(){return `<div class="panel"><h2>첫 번째 에디션 · 수록 범위</h2><p>1956년 발롱도르 출범부터 2026년까지 탐색할 수 있는 축구 역사 아카이브입니다. 모든 축구 기록을 완전히 재현한 데이터베이스는 아닙니다. 수록되지 않은 항목은 추정으로 채우지 않습니다.</p><div class="coverage"><div><b>71</b><small>연도별 발롱도르 기록 (취소 포함)</small></div><div><b>${D.teams.length} / ${D.teams.length*11}</b><small>클래식 팀·시즌 / 선발 선수 기록</small></div><div><b>${D.transfers.length}</b><small>선별한 주요 이적</small></div></div><p>유럽 챔피언 71개 시즌, 주요 대회 ${D.competitions.length}개 계보를 포함합니다. 팀 명단은 해당 유럽 결승 선발 11명으로, 시즌 전체 스쿼드가 아닙니다. 포메이션과 유니폼은 이해를 돕는 도식이며 당시 실제 경기 위치·킷의 정확한 복원이 아닙니다.</p></div><div class="panel"><h2>엠블럼과 영상 안내</h2><p>과거 공식 엠블럼 이미지 원본은 아직 확보되지 않았습니다. 클럽 카드에는 현재 식별용 엠블럼을 표시합니다. 당시 디자인과 다를 수 있습니다. 경기 중계나 풀매치 영상은 호스팅하지 않으며, UEFA의 공식 시즌 페이지에서 제공되는 경기 기록·영상을 확인할 수 있습니다.</p><p>실시간 경기·이적 피드와 자동 갱신은 연결되지 않았습니다. 최종 자료 확인: 2026년 10월 31일. 2026년 발롱도르와 챔피언스리그 결과는 아래 UEFA 자료로 확인했습니다.</p></div><div class="panel"><h2>원본 자료</h2><ul class="source-list"><li><a href="${awardSource}" target="_blank" rel="noopener">UEFA · 남자 발롱도르 역대 수상자</a></li><li><a href="https://www.uefa.com/uefachampionsleague/history/" target="_blank" rel="noopener">UEFA · 유러피언컵 / 챔피언스리그 시즌 아카이브</a></li><li><a href="${D.teams[0].source}" target="_blank" rel="noopener">Real Madrid · 1956년 결승 결과와 양 팀 선발</a></li><li><a href="${D.teams[6].source}" target="_blank" rel="noopener">UEFA · 2009년 결승 공식 선발 명단 (PDF)</a></li><li><a href="https://www.uefa.com/uefachampionsleague/news/02a5-20901454177c-738c0ac757df-1000--champions-league-final-meet-the-teams/" target="_blank" rel="noopener">UEFA · 2025/26 챔피언 파리 생제르맹</a></li><li><a href="https://www.transfermarkt.com/transfers/transferrekorde/statistik/top" target="_blank" rel="noopener">Transfermarkt · 이적 역사 참고</a></li><li><a href="https://unsplash.com/photos/1522778119026-d647f0596c20" target="_blank" rel="noopener">Unsplash · 경기장 분위기 사진 (역사적 해당 경기의 사진 아님)</a></li></ul><p>각 팀과 이적 기록에서도 해당 시즌 원문으로 이동할 수 있습니다. 한국어 이름은 통용 표기를 사용했습니다.</p><button class="year-bookmark" id="export">수록 데이터 JSON 내려받기 ↓</button></div>`}
function render(){const [title,desc]=titles[page]||titles.overview;$('#pageTitle').innerHTML=title+'<span>.</span>';$('#pageDesc').textContent=desc;$('#crumb').textContent=pages[page]?.[1]||title;$('#nav').innerHTML=Object.entries(pages).map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}"><i>${v[0]}</i><span>${v[1]}</span></button>`).join('');$('#yearSelect').value=year;$('#yearRange').value=year;$('#prev').disabled=year<=1956;$('#next').disabled=year>=2026;$('#seasonLabel').textContent=season()+' 시즌 종료 연도';$('#decades').innerHTML=[1956,1960,1970,1980,1990,2000,2010,2020,2026].map(y=>`<button data-year="${y}" class="${(y===1956?year<1960:y===2026?year===2026:Math.floor(year/10)===y/10&&year!==2026)?'active':''}">${y}</button>`).join('');$('#content').innerHTML=({overview,teams:teamsPage,players:playersPage,competitions:competitionPage,transfers:transferPage,favorites:favoritesPage,awards:awardsPage,sources:sourcesPage}[page]||overview)();}
function setYear(y){year=Math.max(1956,Math.min(2026,+y));render();syncHash()}
function navigate(p){page=titles[p]?p:'overview';scope='year';query='';render();syncHash();window.scrollTo({top:0,behavior:'smooth'})}
function syncHash(){history.replaceState(null,'','#'+page+'/'+year)}
function modal(title,sub,body){$('#modalContent').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="close" data-close aria-label="닫기">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function openTeam(i){let t=D.teams[i];if(!t)return;let rows=['GK','DF','MF','FW'].map(pos=>t.players.filter(p=>p.pos===pos));modal(`${t.name} · ${t.year}`,`${t.year-1}/${String(t.year).slice(-2)} 유럽 결승 선발 · 감독 ${t.coach}`,`<div class="lineup-layout"><div class="pitch" style="--c1:${t.colors[0]};--c2:${t.colors[1]}">${rows.map(r=>`<div class="pitch-row">${r.map(p=>`<div class="pitch-player"><div class="shirt">${p.pos}</div>${p.name}</div>`).join('')}</div>`).join('')}</div><div><div class="section-heading"><h2>STARTING XI</h2><span class="chip">${t.formation}</span>${saveBtn('team:'+i)}</div><div class="roster">${t.players.map(p=>`<div><small>${p.pos}</small><span>${p.name}</span></div>`).join('')}</div></div></div><p class="note">실제 결승 선발 명단입니다. 포메이션은 참고 도식이며, 셔츠 색상은 구분용입니다. 당시 공식 엠블럼과 정확한 경기 유니폼은 미수록입니다.</p><a class="source-link" href="${t.source}" target="_blank" rel="noopener">공식 경기 기록 확인 ↗</a>`)}
function openAward(y){modal(`${y} BALLON D’OR`,y===2020?'시상 취소':'남자 발롱도르',`<div class="wide-hero"><div class="trophy"><div class="gold-ball">⬡</div></div><h2 style="font:700 28px 'Noto Sans KR',sans-serif;text-align:center">${D.awards[y]}</h2></div><p class="note">발롱도르는 달력 연도의 시상 기록입니다. 클럽 대회의 종료 연도와 구분해서 보세요.${y===2020?' 코로나19의 영향으로 2020년에는 시상하지 않았습니다.':''}</p><a class="source-link" target="_blank" rel="noopener" href="${awardSource}">UEFA 역대 수상자 원문 ↗</a><button class="year-bookmark" style="float:right" data-jump="${y}">${y}년 아카이브로 이동 →</button>`)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function openSearch(){modal('기록 속으로','선수 이름, 클럽, 발롱도르 수상자 또는 연도 검색',`<div class="search-modal"><input id="globalSearch" type="search" placeholder="예: 박지성, 레알 마드리드, 2009" aria-label="아카이브 전체 검색"><div id="results" class="search-results"><p class="note">1956년부터 2026년까지 수록된 기록을 검색합니다.</p></div></div>`);setTimeout(()=>$('#globalSearch').focus(),20)}
function searchResults(q){if(!q.trim())return $('#results').innerHTML='<p class="note">이름이나 연도를 입력하세요.</p>';let out=[];D.teams.forEach((t,i)=>{if((t.name+' '+t.en+' '+t.year).toLowerCase().includes(q.toLowerCase()))out.push(`<button data-team="${i}">${t.name}<small>${t.year} · 팀</small></button>`);t.players.forEach((p,j)=>{if(p.name.includes(q))out.push(`<button data-player="${i}:${j}">${p.name}<small>${t.name} · ${t.year}</small></button>`)})});Object.entries(D.awards).forEach(([y,n])=>{if((y+' '+n).includes(q))out.push(`<button data-award="${y}">${n}<small>${y} · 발롱도르</small></button>`)});$('#results').innerHTML=out.slice(0,30).join('')||'<p class="note">수록된 기록에서 검색 결과가 없습니다.</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,[data-team]');if(!b)return;if(b.dataset.save){e.stopPropagation();let k=b.dataset.save;const exists=saved.includes(k);saved=exists?saved.filter(x=>x!==k):[...saved,k];try{localStorage.setItem('football-archive-saved',JSON.stringify(saved));toast(exists?'컬렉션에서 제거했습니다.':'컬렉션에 저장했습니다.')}catch{toast('브라우저 저장 공간을 사용할 수 없습니다.')}b.textContent=exists?'☆':'★';b.classList.toggle('saved',!exists);b.setAttribute('aria-pressed',String(!exists));render();return}if(b.dataset.page){$('#modal').close();navigate(b.dataset.page)}else if(b.dataset.year){setYear(b.dataset.year)}else if(b.dataset.jump){$('#modal').close();year=+b.dataset.jump;navigate('overview')}else if(b.dataset.team!==undefined)openTeam(+b.dataset.team);else if(b.dataset.player){let[i,j]=b.dataset.player.split(':').map(Number),t=D.teams[i],p=t.players[j];modal(p.name,`${t.year} · ${t.name} · ${p.pos}`,`<div class="panel"><h2>결승 선발 출전 기록</h2><p>${t.year-1}/${String(t.year).slice(-2)} 유럽 결승의 ${t.name} 선발 11명에 포함됩니다.</p><p>선수의 전체 커리어, 개인 시즌 통계는 아직 수록되지 않았습니다.</p><button class="year-bookmark" data-team="${i}">전체 선발 명단 보기 →</button></div><a href="${t.source}" class="source-link" target="_blank" rel="noopener">경기 기록 원문 ↗</a>`)}else if(b.dataset.award)openAward(+b.dataset.award);else if(b.dataset.scope){scope=b.dataset.scope;render()}else if(b.hasAttribute('data-all')){scope='all';if(page==='overview'){page='teams'}render();syncHash()}else if(b.hasAttribute('data-close'))$('#modal').close();else if(b.id==='export'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'}));a.download='football-archive-1956-2026.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}});
document.addEventListener('input',e=>{if(e.target.id==='globalSearch')searchResults(e.target.value);if(e.target.id==='filter'){let pos=e.target.selectionStart;query=e.target.value;render();$('#filter').focus();if($('#filter').type!=='search')$('#filter').setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();openSearch()}if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('club-card')){e.preventDefault();openTeam(+e.target.dataset.team)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#prev').onclick=()=>setYear(year-1);$('#next').onclick=()=>setYear(year+1);$('#latest').onclick=()=>setYear(2026);$('#yearRange').oninput=e=>setYear(e.target.value);$('#yearSelect').onchange=e=>setYear(e.target.value);$('#searchOpen').onclick=openSearch;$('#favoritesOpen').onclick=()=>navigate('favorites');
$('#yearSelect').innerHTML=Array.from({length:71},(_,i)=>`<option value="${1956+i}">${1956+i}</option>`).join('');
Promise.all([fetch('data.json').then(r=>{if(!r.ok)throw Error('data');return r.json()}),fetch('replay/localization.json').then(r=>r.json())]).then(([d,l])=>{D=d;LocaleData=l;let [p,y]=location.hash.slice(1).split('/');if(titles[p])page=p;if(y&&+y>=1956&&+y<=2026)year=+y;render()}).catch(()=>{$('#content').innerHTML='<div class="empty">기록을 불러오지 못했습니다. 페이지를 새로고침해 주세요.</div>'});

window.addEventListener('hashchange',()=>{if(!D)return;let[p,y]=location.hash.slice(1).split('/');if(titles[p])page=p;if(+y>=1956&&+y<=2026)year=+y;scope='year';query='';render()});
